changeSet.sql:
update section s set s.value_formula = replace(s.value_formula, 'LBL_', 'TOT_' ) where s.value_formula like '%LBL_%';
update section s set s.base_formula = replace(s.base_formula, 'LBL_', 'TOT_' ) where s.base_formula like '%LBL_%';
update section s set s.rate_formula = replace(s.rate_formula, 'LBL_', 'TOT_' ) where s.rate_formula like '%LBL_%';
